from .repo import TaskManagerRepo
from .schemas import TaskCreateRequest, TaskResponse, TaskUpdateRequest, TaskUpdateResponse, TaskDeleteResponse
from mozaiksai.core.runtime import ModuleInputValidationError

class TaskManagerService:
    def __init__(self, repo=None):
        self.repo = repo or TaskManagerRepo()

    async def create_task(self, *, ctx, title: str, description: str = None) -> TaskResponse:
        if not title:
            raise ModuleInputValidationError('Title is required.')
        payload = TaskCreateRequest(title=title, description=description)
        record = await self.repo.create_task(context=ctx, payload=payload)
        event_payload = {'task_id': record['task_id']}  
        await ctx.emit('domain.tasks.task_created', event_payload)
        return TaskResponse(task_id=record['task_id'])

    async def update_task(self, *, ctx, task_id: str, title: str = None, description: str = None) -> TaskUpdateResponse:
        if not task_id:
            raise ModuleInputValidationError('Task ID is required.')
        payload = TaskUpdateRequest(task_id=task_id, title=title, description=description)
        success = await self.repo.update_task(context=ctx, payload=payload)
        if success:
            event_payload = {'task_id': task_id}
            await ctx.emit('domain.tasks.task_updated', event_payload)
        return TaskUpdateResponse(success=success)

    async def delete_task(self, *, ctx, task_id: str) -> TaskDeleteResponse:
        if not task_id:
            raise ModuleInputValidationError('Task ID is required.')
        success = await self.repo.delete_task(context=ctx, task_id=task_id)
        if success:
            event_payload = {'task_id': task_id}
            await ctx.emit('domain.tasks.task_deleted', event_payload)
        return TaskDeleteResponse(success=success)

    async def summarize_tasks(self, *, ctx):
        return await self.repo.summarize_tasks(context=ctx)

async def get_tasks(ctx, *, id):
    from . import repo
    result = await repo.get_tasks(ctx, id=id)
    fields = ['task_id', 'user_id', 'title', 'description', 'is_completed', 'created_at', 'updated_at']
    record = result['item']
    item = {field: str(record[field]) if field == '_id' else record[field] for field in fields if field in record}
    return {'item': item}

async def list_tasks(ctx, *, page=1, page_size=20, search=None):
    from . import repo
    result = await repo.list_tasks(ctx, page=page, page_size=page_size, search=search)
    fields = ['task_id', 'user_id', 'title', 'description', 'is_completed', 'created_at', 'updated_at']
    items = [{field: str(record[field]) if field == '_id' else record[field] for field in fields if field in record} for record in result['items']]
    return {'items': items, 'total': result['total']}

